package net.officefloor.hq.app.claim;

import java.math.BigDecimal;
import java.math.RoundingMode;
import java.time.LocalDate;
import net.officefloor.hq.app.period.Periods;
import net.officefloor.hq.app.person.People;
import net.officefloor.hq.app.rate.Rates;
import net.officefloor.hq.app.setting.Settings;
import net.officefloor.hq.app.sheet.Sheets;
import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;

public class ApplyClaimStatus {
    public void apply(@Val ValidClaimStatus request, @Val Claim claim, Sheets sheets, People people,
            Rates rates, Periods periods, Settings settings, ClaimNumbering numbering, ClaimLog log, Out<ClaimNumber> number)
            throws ClaimStatusRefusedException {
        number.set(change(request, claim, sheets, people, rates, periods, settings, numbering, log));
    }

    /** Applies a status change to the claim by the rules of a single change, returning its number;
     *  throws, leaving the claim as it is, when the change is refused. Bulk settle uses it too. */
    static ClaimNumber change(ValidClaimStatus request, Claim claim, Sheets sheets, People people,
            Rates rates, Periods periods, Settings settings, ClaimNumbering numbering, ClaimLog log)
            throws ClaimStatusRefusedException {
        RoundingMode rounding = Rounding.of(claim, settings.policyDate(claim.getSheetId()));
        if (periods.isClosed(claim.getSheetId(), claim.getPeriodDate())) {
            throw new ClaimStatusRefusedException("No claim whose due-by is inside a closed period can change status");
        }
        boolean steward = Settings.STEWARD.equals(settings.role(claim.getSheetId(), request.user()));
        if (request.decision() == ValidClaimStatus.Decision.NONE) {
            // Opening, settling and voiding are each taken only by the roles the sheet's permission allows.
            String action = switch (request.target()) {
                case OPEN -> "open";
                case SETTLED -> "settle";
                default -> "void";
            };
            if (!settings.allows(claim.getSheetId(), request.user(), action)) {
                throw new ClaimStatusRefusedException("Your role may not " + action + " a claim on this sheet");
            }
        }
        if (request.decision() != ValidClaimStatus.Decision.NONE) {
            // Only a steward approves or rejects, and only a PENDING claim.
            if (claim.getStatus() != ClaimStatus.PENDING) {
                throw new ClaimStatusRefusedException(claim.getStatus(), request.target());
            }
            if (!steward) {
                throw new ClaimStatusRefusedException("Only a steward can approve or reject a PENDING claim");
            }
        } else if (!claim.getStatus().canBecome(request.target())) {
            throw new ClaimStatusRefusedException(claim.getStatus(), request.target());
        }
        if (request.target() == ClaimStatus.SETTLED && claim.getOpenedBy() != null
                && claim.getOpenedBy().equals(request.user())) {
            // Four eyes: the user who opened a claim cannot settle (or approve) it.
            throw new ClaimStatusRefusedException("The user who opened a claim cannot settle it");
        }
        if (request.target() == ClaimStatus.SETTLED && claim.isDeferredOn(sheets.today(claim.getSheetId()))) {
            throw new ClaimStatusRefusedException("A deferred claim cannot be settled until its deferred-until date");
        }
        if (request.target() == ClaimStatus.VOID && claim.getStatus() == ClaimStatus.SETTLED) {
            // Only a steward voids a SETTLED claim, and only within 7 days of its settlement by the sheet's today.
            if (!steward) {
                throw new ClaimStatusRefusedException("Only a steward can void a SETTLED claim");
            }
            LocalDate settledOn = log.settledOn(claim);
            if (settledOn == null || sheets.today(claim.getSheetId()).isAfter(settledOn.plusDays(7))) {
                throw new ClaimStatusRefusedException("A SETTLED claim can be voided only within 7 days of its settlement");
            }
        }
        ClaimStatus target = request.target();
        if (target == ClaimStatus.OPEN && request.decision() == ValidClaimStatus.Decision.NONE) {
            refuseNoteless(claim, sheets, people, rates, settings, rounding);
        }
        if (target == ClaimStatus.SETTLED && claim.getProofs() == 0) {
            // Above the proof threshold in force on the claim's date a claim needs a proof to be settled or approved,
            // judged on its due as shown (before the clerk limit is considered); a due of n/a is within any threshold.
            BigDecimal threshold = settings.proofThreshold(claim.getSheetId(), claim.getDate());
            BigDecimal due = shownDue(claim, sheets, people, rates, settings, rounding);
            if (threshold != null && due != null && due.compareTo(threshold) > 0) {
                throw new ClaimStatusRefusedException("A claim whose due is above the proof threshold needs a proof to be settled");
            }
        }
        if (target == ClaimStatus.SETTLED && request.decision() == ValidClaimStatus.Decision.NONE && !steward) {
            // A clerk settles only within the sheet's clerk limit, judged on the claim's due as shown;
            // a due of n/a is within any limit.
            BigDecimal limit = settings.clerkLimit(claim.getSheetId());
            BigDecimal due = shownDue(claim, sheets, people, rates, settings, rounding);
            if (limit != null && due != null && due.compareTo(limit) > 0) {
                // Above the clerk limit the claim awaits a steward's approval.
                target = ClaimStatus.PENDING;
            }
        }
        if (target == ClaimStatus.OPEN && request.decision() == ValidClaimStatus.Decision.NONE) {
            claim.setNumber(numbering.next(claim.getSheetId(), claim.getPeriodDate()));
            claim.setOpenedBy(request.user());
        }
        // A voided claim keeps its number; numbers are never reused.
        ClaimNumber number = new ClaimNumber(claim.getNumber());
        if (target == ClaimStatus.SETTLED) {
            // Settling (or approving) fixes the due: the figure a statement bound it to (never while PENDING), else its amount
            // at the rate in force on the claim's date, with its late charge as of today on top and raised to the floor, frozen in;
            // with no figure it stays live (n/a until a rate is set).
            String grade = people.find(claim.getSheetId(), claim.getPersonId()).gradeOn(claim.getDate());
            BigDecimal figure = claim.isBound() && claim.getStatedDue() != null ? claim.getStatedDue()
                    : Rates.due(claim.getAmount(), rates.find(claim.getSheetId(), grade, claim.getDate()), rounding);
            claim.setSettledDue(LateCharge.due(claim, figure, settings.floor(claim.getSheetId(), claim.getDate()),
                    on -> settings.latePct(claim.getSheetId(), on), sheets.today(claim.getSheetId()), rounding,
                    settings.grace(claim.getSheetId(), grade, claim.getDate())));
        }
        // A rejected claim is OPEN again, so bound again by the last statement if it included it.
        if (target == ClaimStatus.VOID) {
            claim.setVoidReason(request.reason());
        }
        claim.setStatus(target);
        return number;
    }

    /** Refuses opening a claim with an empty note whose due as shown is above the note threshold in force on its date;
     *  a due of n/a is within any threshold. Bulk open uses it too. */
    static void refuseNoteless(Claim claim, Sheets sheets, People people, Rates rates, Settings settings,
            RoundingMode rounding) throws ClaimStatusRefusedException {
        if (claim.getNote() != null && !claim.getNote().trim().isEmpty()) {
            return;
        }
        BigDecimal threshold = settings.noteThreshold(claim.getSheetId(), claim.getDate());
        if (threshold == null) {
            return;
        }
        BigDecimal due = shownDue(claim, sheets, people, rates, settings, rounding);
        if (due != null && due.compareTo(threshold) > 0) {
            throw new ClaimStatusRefusedException("A claim whose due is above the note threshold needs a note to be opened");
        }
    }

    /** The claim's due as shown: fixed (settled or bound), else its live figure with its late charge as of today; null for n/a. */
    private static BigDecimal shownDue(Claim claim, Sheets sheets, People people, Rates rates, Settings settings,
            RoundingMode rounding) {
        String grade = people.find(claim.getSheetId(), claim.getPersonId()).gradeOn(claim.getDate());
        BigDecimal fixed = ClaimResponse.fixedDue(claim);
        BigDecimal figure = fixed != null || claim.isBound() ? fixed
                : Rates.due(claim.getAmount(), rates.find(claim.getSheetId(), grade, claim.getDate()), rounding);
        return LateCharge.due(claim, figure, settings.floor(claim.getSheetId(), claim.getDate()),
                on -> settings.latePct(claim.getSheetId(), on), sheets.today(claim.getSheetId()), rounding,
                settings.grace(claim.getSheetId(), grade, claim.getDate()));
    }
}
package net.officefloor.hq.app.claim;

import java.util.HashSet;
import java.util.List;
import java.util.Set;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.period.Periods;
import net.officefloor.hq.app.person.People;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.Watches;
import net.officefloor.hq.app.rate.Rates;
import net.officefloor.hq.app.rollup.Rollup;
import net.officefloor.hq.app.rollup.RollupFigures;
import net.officefloor.hq.app.setting.Settings;
import net.officefloor.hq.app.sheet.Sheets;
import net.officefloor.web.ObjectResponse;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.RequestBody;

/**
 * Settles the selected claims in list order (people in the order they were added, newest claim first
 * within a person), each by exactly the rules of settling one claim and audited as a single settle
 * would be. A claim that goes to PENDING counts as settled; a selected claim that cannot be settled is
 * left as it is and counted as refused; so is a selected id that is not a claim on the sheet.
 */
public class BulkSettleClaims {
    public void settle(@PathVariable("sheetId") String sheetId, @RequestBody BulkSettleRequest request,
            Claims claims, Sheets sheets, People people, Rates rates, Periods periods, Settings settings,
            ClaimNumbering numbering, Rollup rollup, Audit audit, ClaimLog log, Watches watches,
            ObjectResponse<BulkSettleResponse> response) {
        Set<String> selected = new HashSet<>(request.claimIds() == null ? List.of() : request.claimIds());
        ValidClaimStatus settle = new ValidClaimStatus(ClaimStatus.SETTLED, request.user(),
                ValidClaimStatus.Decision.NONE, null);
        List<Claim> all = claims.list(sheetId);
        int settled = 0;
        for (Person person : people.list(sheetId)) {
            for (Claim claim : all) {
                if (claim.getPersonId() != person.getId() || !selected.contains(String.valueOf(claim.getId()))) {
                    continue;
                }
                RollupFigures before = rollup.figures(sheetId);
                ClaimNumber number;
                try {
                    number = ApplyClaimStatus.change(settle, claim, sheets, people, rates, periods, settings, numbering, log);
                } catch (ClaimStatusRefusedException refused) {
                    continue;
                }
                claims.save(claim);
                AuditClaimStatus.record(settle, claim, number, people, audit, before, rollup, log, watches);
                settled++;
            }
        }
        response.send(new BulkSettleResponse(settled, selected.size() - settled));
    }
}
package net.officefloor.hq.app.claim;

import java.math.BigDecimal;
import java.time.LocalDate;

/** A claim by a person on a sheet. Mutable so an Apply step can change it in place. */
public class Claim {

    private final long id;
    private final String sheetId;
    private long personId;
    private BigDecimal amount;
    private LocalDate date;
    private String note;
    private ClaimStatus status;
    private String number;
    private BigDecimal settledDue;
    private String openedBy;
    private boolean stated;
    private BigDecimal statedDue;
    private String corrects;
    private LocalDate correctedDate;
    private LocalDate dueBy;
    private LocalDate deferredUntil;
    private int proofs;
    private String splitFrom;
    private java.util.List<String> log = java.util.List.of();

    public Claim(long id, String sheetId, long personId, BigDecimal amount, LocalDate date, String note,
            ClaimStatus status, String number, BigDecimal settledDue, String openedBy) {
        this.id = id;
        this.sheetId = sheetId;
        this.personId = personId;
        this.amount = amount;
        this.date = date;
        this.note = note;
        this.status = status;
        this.number = number;
        this.settledDue = settledDue;
        this.openedBy = openedBy;
    }

    public long getId() { return id; }
    public String getSheetId() { return sheetId; }
    public long getPersonId() { return personId; }
    public BigDecimal getAmount() { return amount; }
    public LocalDate getDate() { return date; }
    public String getNote() { return note; }
    public ClaimStatus getStatus() { return status; }
    /** The number given when the claim was opened (sheet-wide, or <period>-<n> / X-<n> within its period); null for a draft (a voided claim keeps the number it had). */
    public String getNumber() { return number; }
    /** The due fixed when the claim was settled; null while its due is live. */
    public BigDecimal getSettledDue() { return settledDue; }
    /** The user who opened the claim; null if it was never opened. */
    public String getOpenedBy() { return openedBy; }
    public void setPersonId(long personId) { this.personId = personId; }
    public void setAmount(BigDecimal amount) { this.amount = amount; }
    public void setDate(LocalDate date) { this.date = date; }
    public void setNote(String note) { this.note = note; }
    public void setStatus(ClaimStatus status) { this.status = status; }
    public void setNumber(String number) { this.number = number; }
    /** Whether the person's last statement bound this claim to a figure. */
    public boolean isStated() { return stated; }
    /** The figure the last statement bound this claim to; null when unbound or when it was n/a. */
    public BigDecimal getStatedDue() { return statedDue; }
    /** Whether the last statement binds this claim's figure now: a PENDING claim is not bound (it shows its live figure). */
    public boolean isBound() { return stated && status != ClaimStatus.PENDING; }
    public void setStated(boolean stated) { this.stated = stated; }
    public void setStatedDue(BigDecimal statedDue) { this.statedDue = statedDue; }
    public void setSettledDue(BigDecimal settledDue) { this.settledDue = settledDue; }
    public void setOpenedBy(String openedBy) { this.openedBy = openedBy; }
    /** The number of the SETTLED claim this correction corrects; null for any claim that is not a correction. */
    public String getCorrects() { return corrects; }
    public void setCorrects(String corrects) { this.corrects = corrects; }
    /** The date of the claim this correction corrects; null when it is not a correction or that claim is not found. */
    public void setCorrectedDate(LocalDate correctedDate) { this.correctedDate = correctedDate; }
    public LocalDate getCorrectedDate() { return correctedDate; }
    /** The date the claim's rounding goes by: a correction's is the date of the claim it corrects, any other claim's its own. */
    public LocalDate getRoundingDate() { return correctedDate != null ? correctedDate : date; }
    /** The claim's due-by, fixed when it was created: its date plus the first of its person's own terms, their grade's terms and the sheet's terms in force on that date. */
    public LocalDate getDueBy() { return dueBy; }
    public void setDueBy(LocalDate dueBy) { this.dueBy = dueBy; }
    /** The date that places the claim in its period: its due-by as fixed at creation (its date when it has none). */
    public LocalDate getPeriodDate() { return dueBy != null ? dueBy : date; }
    /** The date the claim was last deferred until; null if it was never deferred. */
    public LocalDate getDeferredUntil() { return deferredUntil; }
    public void setDeferredUntil(LocalDate deferredUntil) { this.deferredUntil = deferredUntil; }
    /** Whether the claim is deferred on the date: OPEN and deferred until a later date. A deferred claim counts in no
     *  total, is not overdue, cannot be settled and is left unbound by a statement. */
    public boolean isDeferredOn(LocalDate today) {
        return status == ClaimStatus.OPEN && deferredUntil != null && today.isBefore(deferredUntil);
    }
    /** The last day (the sheet's today then) a reminder was written for the claim; null if it was never reminded. */
    private LocalDate remindedOn;
    public LocalDate getRemindedOn() { return remindedOn; }
    public void setRemindedOn(LocalDate remindedOn) { this.remindedOn = remindedOn; }
    /** The claim's proofs count: raised by one at a time. */
    public int getProofs() { return proofs; }
    public void setProofs(int proofs) { this.proofs = proofs; }
    /** The number of the claim this claim was split from; null for any claim a split did not make. */
    public String getSplitFrom() { return splitFrom; }
    public void setSplitFrom(String splitFrom) { this.splitFrom = splitFrom; }

    /** Whether the claim was added while its period was soft-closed. */
    private boolean lateEntry;
    public boolean isLateEntry() { return lateEntry; }
    public void setLateEntry(boolean lateEntry) { this.lateEntry = lateEntry; }

    /** The claim's external reference; null when it has none. */
    private String ref;
    public String getRef() { return ref; }
    public void setRef(String ref) { this.ref = ref; }

    /** The claim's tags: lower-cased, sorted and comma separated; null when it has none. */
    private String tags;
    public String getTags() { return tags; }
    public void setTags(String tags) { this.tags = tags; }

    /** The reason the claim was voided with, from the sheet's list; null when none. */
    private String voidReason;
    public String getVoidReason() { return voidReason; }
    public void setVoidReason(String voidReason) { this.voidReason = voidReason; }

    /** The user whose open editor locks the claim; null when unlocked. */
    private String lockedBy;
    public String getLockedBy() { return lockedBy; }
    public void setLockedBy(String lockedBy) { this.lockedBy = lockedBy; }
    /** A correction is a claim with a negative amount: its due has no floor and no late charge. */
    public boolean isCorrection() { return amount.signum() < 0; }
    /** The claim's status log, oldest first: one "<STATUS> by <user> on <date> due=<due>" line per status it has had. */
    public java.util.List<String> getLog() { return log; }
    public void setLog(java.util.List<String> log) { this.log = log; }
    private java.util.List<ClaimComment> comments = java.util.List.of();
    /** The claim's comments, oldest first (empty unless listed). */
    public java.util.List<ClaimComment> getComments() { return comments; }
    public void setComments(java.util.List<ClaimComment> comments) { this.comments = comments; }
    /** The status the claim had at the end of the day, as its status log records it (each line dated the sheet's
     *  today when the change was made); null when it was added after that day. */
    public ClaimStatus statusAt(LocalDate end) {
        ClaimStatus at = null;
        for (String line : log) {
            int on = line.lastIndexOf(" on ");
            int due = line.indexOf(" due=", on);
            if (on < 0 || due < 0) continue;
            if (!LocalDate.parse(line.substring(on + 4, due)).isAfter(end)) {
                at = ClaimStatus.valueOf(line.substring(0, line.indexOf(' ')));
            }
        }
        return at;
    }
}
package net.officefloor.hq.app.claim;

import java.time.LocalDate;
import net.officefloor.hq.app.period.Periods;
import net.officefloor.hq.app.person.People;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.sheet.Sheets;
import net.officefloor.plugin.variable.Val;

public class ApplyClaim {
    public void apply(@Val ValidClaim request, @Val Claim claim, Sheets sheets, Periods periods, People people, Claims claims)
            throws InvalidClaimException {
        if (claim.getStatus() != ClaimStatus.DRAFT) {
            // Only a draft can be edited; to change an open claim, void it and add a new one.
            throw new InvalidClaimException("Only a DRAFT claim can be edited");
        }
        String lockedBy = claims.lockedBy(claim);
        if (lockedBy != null && !lockedBy.equals(request.user())) {
            throw new InvalidClaimException("The claim is being edited by " + lockedBy);
        }
        LocalDate date = request.date() != null ? request.date() : sheets.today(claim.getSheetId());
        if (periods.isClosed(claim.getSheetId(), claim.getPeriodDate())) {
            throw new InvalidClaimException("No claim whose due-by is inside a closed period can be edited");
        }
        Person person = people.find(claim.getSheetId(), claim.getPersonId());
        if (person != null && !person.allowsClaimOn(date)) {
            throw new InvalidClaimException("No claim can be dated after the person's retirement date");
        }
        ValidateClaim.checkCorrects(request, claim.getSheetId(), claim.getPersonId(), claims);
        ValidateClaim.checkRef(request.ref(), claim.getSheetId(), claim.getId(), claims);
        claim.setAmount(request.amount());
        claim.setRef(request.ref());
        claim.setTags(request.tags());
        claim.setCorrects(request.corrects());
        claim.setCorrectedDate(claims.correctedDate(claim.getSheetId(), claim.getPersonId(), request.corrects()));
        claim.setDate(date);
        claim.setNote(request.note());
    }
}
